document.addEventListener("DOMContentLoaded",init);const CATEGORY_PAGE_SIZE=12;let currentCategory="";let categoryProducts=[];let shownCount=CATEGORY_PAGE_SIZE;let searchTerm="";let siteQuery="";let currentType="";let featuredProducts=null;const categoryCache={};async function init(){renderRail();document.getElementById("category-more").addEventListener("click",onShowMore);homeMoreButton();wireBrowseSearch();loadFeatured();currentType=getQueryParam("type")||"";const q=(getQueryParam("q")||"").trim();if(q){document.getElementById("browse-search-input").value=q;await runSiteSearch(q,{replaceUrl:false});return}const requested=getQueryParam("category");const known=activeCategories().some(c=>c.id===requested);await selectCategory(known?requested:activeCategories()[0].id,{replaceUrl:false})}async function runSiteSearch(q,opts){siteQuery=q;currentCategory="";searchTerm="";shownCount=CATEGORY_PAGE_SIZE;markSelected("");const pane=document.querySelector(".category-pane");if(pane)pane.scrollTop=0;document.getElementById("category-pane-heading").textContent=`Results for "${q}"`;document.title=`${q} — Mwakete`;if(!opts||opts.replaceUrl!==false){history.replaceState(null,"",`${location.pathname}?q=${encodeURIComponent(q)}`)}const statusEl=document.getElementById("category-status");const listEl=document.getElementById("category-list");listEl.innerHTML="";document.getElementById("category-more").hidden=true;hideDiscovery();const stopLoading=startLoadingMessage(statusEl);const res=await Api.get("searchProducts",{q:q,type:currentType});stopLoading();if(!res||!res.ok){showLoadFailedMessage(statusEl);return}categoryProducts=res.products||[];render()}function renderRail(){document.getElementById("category-rail").innerHTML=activeCategories().map(c=>`\n    <button type="button" class="category-rail-item" data-category="${escapeHtml(c.id)}" aria-pressed="false">\n      <span class="category-rail-label">${escapeHtml(c.label)}</span>\n    </button>\n  `).join("");document.getElementById("category-rail").addEventListener("click",e=>{const btn=e.target.closest(".category-rail-item");if(btn)selectCategory(btn.dataset.category)})}function markSelected(categoryId){document.querySelectorAll(".category-rail-item").forEach(btn=>{const on=btn.dataset.category===categoryId;btn.classList.toggle("is-selected",on);btn.setAttribute("aria-pressed",on?"true":"false")})}async function selectCategory(categoryId,opts){if(categoryId===currentCategory)return;if(siteQuery){siteQuery="";hideDiscovery();const input=document.getElementById("browse-search-input");if(input)input.value=""}currentCategory=categoryId;shownCount=CATEGORY_PAGE_SIZE;markSelected(categoryId);const pane=document.querySelector(".category-pane");if(pane)pane.scrollTop=0;const meta=categoryById(categoryId);document.getElementById("category-pane-heading").textContent=meta?meta.label:"Browse";document.title=`${meta?meta.label:"Browse"} — Mwakete`;if(!opts||opts.replaceUrl!==false){const params=new URLSearchParams;params.set("category",categoryId);if(currentType)params.set("type",currentType);history.replaceState(null,"",`${location.pathname}?${params.toString()}`)}if(categoryCache[categoryId]){categoryProducts=categoryCache[categoryId];render();return}const statusEl=document.getElementById("category-status");const listEl=document.getElementById("category-list");listEl.innerHTML="";document.getElementById("category-more").hidden=true;const stopLoading=startLoadingMessage(statusEl);const request=Api.get("searchProducts",{category:categoryId,type:currentType});window.__criticalReady=request;const res=await request;stopLoading();if(currentCategory!==categoryId)return;if(!res.ok){showLoadFailedMessage(statusEl);return}categoryProducts=res.products||[];categoryCache[categoryId]=categoryProducts;render()}function wireBrowseSearch(){const form=document.getElementById("browse-search-form");const input=document.getElementById("browse-search-input");if(!form||!input)return;form.addEventListener("submit",e=>{e.preventDefault();const q=input.value.trim();if(!q)return;runSiteSearch(q)});input.addEventListener("input",()=>{if(siteQuery)return;searchTerm=input.value.trim().toLowerCase();shownCount=CATEGORY_PAGE_SIZE;render()})}function matchesSearch(p){if(!searchTerm)return true;return`${p.name||""} ${p.description||""}`.toLowerCase().includes(searchTerm)}function render(){const statusEl=document.getElementById("category-status");const listEl=document.getElementById("category-list");const moreEl=document.getElementById("category-more");const matches=categoryProducts.filter(matchesSearch);renderFeatured();if(matches.length===0){listEl.innerHTML="";moreEl.hidden=true;if(siteQuery){statusEl.textContent=`No exact match for "${siteQuery}".`;runDiscovery();return}statusEl.textContent=searchTerm?`Nothing in this category matches "${searchTerm}".`:"Nothing in this category yet — try another, or search for what you need.";return}hideDiscovery();const page=matches.slice(0,Math.max(CATEGORY_PAGE_SIZE,shownCount));const noun=`product${matches.length===1?"":"s"}`;statusEl.textContent=page.length<matches.length?`Showing ${page.length} of ${matches.length} ${noun}.`:`${matches.length} ${noun}.`;listEl.innerHTML=page.map(renderCategoryTile).join("");moreEl.hidden=page.length>=matches.length;recordProductViewsOnce(page.map(p=>p.productId))}async function loadFeatured(){const res=await Api.get("getTips",{});featuredProducts=res&&res.ok&&Array.isArray(res.products)?res.products:[];renderFeatured()}function renderFeatured(){const strip=document.getElementById("featured-strip");const listEl=document.getElementById("featured-list");if(!strip||!listEl||featuredProducts===null)return;const mine=featuredProducts.filter(p=>categoryIdOf(p.category)===currentCategory).filter(matchesSearch);strip.hidden=mine.length===0;listEl.innerHTML=mine.map(renderCategoryTile).join("")}function renderCategoryTile(product){const media=product.imageUrl?`<img class="category-tile-image" src="${escapeHtml(optimizedImageUrl(product.imageUrl,IMG_W.card))}"${srcsetAttr(product.imageUrl,IMG_SIZES_TILE)} alt="" loading="lazy" decoding="async">`:`<div class="placeholder-swatch category-${escapeHtml(categoryIdOf(product.category))}" aria-hidden="true">${escapeHtml(initials(product.name))}</div>`;return`\n    <a class="category-tile" data-product-id="${escapeHtml(product.productId)}"\n       href="product.html?store=${encodeURIComponent(product.storeSlug)}&product=${encodeURIComponent(product.productId)}">\n      ${media}\n      <span class="category-tile-name">${escapeHtml(product.name)}</span>\n    </a>\n  `}function onShowMore(){shownCount+=CATEGORY_PAGE_SIZE;render()}function homeMoreButton(){const btn=document.getElementById("category-more");const inPage=document.querySelector(".load-more-row");if(!btn||!inPage)return;const mq=window.matchMedia("(max-width: 700px)");const place=()=>{const slot=document.getElementById("bottom-nav-more-slot");const target=mq.matches&&slot?slot:inPage;if(btn.parentElement!==target)target.appendChild(btn)};place();requestAnimationFrame(place);if(mq.addEventListener)mq.addEventListener("change",place);else if(mq.addListener)mq.addListener(place)}let discoveryFor=null;function hideDiscovery(){const el=document.getElementById("search-discovery");if(!el)return;el.hidden=true;el.innerHTML="";discoveryFor=null}function searchOutcome(){const intent=typeof detectSearchIntent==="function"?detectSearchIntent(siteQuery):{confidence:"empty",matches:[],cheap:false};return{query:siteQuery,resultCount:categoryProducts.length,confidence:intent.confidence,cheap:intent.cheap,matches:intent.matches.filter(m=>categoryById(m.category))}}function discoveryHref(match){const params=new URLSearchParams;params.set("category",match.category);if(match.listingType)params.set("type",match.listingType);return"categories.html?"+params.toString()}function renderDiscoveryChips(matches){const lone=matches.length===1;const items=matches.map(m=>{const meta=categoryById(m.category);if(!meta)return"";const text=lone?`See all ${meta.label}`:meta.label;return`<a class="chip-strip-item" href="${escapeAttr(discoveryHref(m))}">${escapeHtml(text)}</a>`}).filter(Boolean).join("");return`<nav class="chip-strip search-discovery-chips" aria-label="Suggested categories">${items}</nav>`}async function runDiscovery(){const el=document.getElementById("search-discovery");if(!el||typeof detectSearchIntent!=="function")return;if(discoveryFor===siteQuery)return;discoveryFor=siteQuery;const outcome=searchOutcome();const matches=outcome.matches;const statusEl=document.getElementById("category-status");if(!matches.length){el.innerHTML=`<p class="search-discovery-lead">${outcome.confidence==="empty"?"What are you looking for?":"Try a product name, a category, a store, or a service."}</p>`+renderDiscoveryChips(popularCategories().map(c=>({category:c.id,listingType:""})));el.hidden=false;statusEl.innerHTML=`<strong>No exact match for "${escapeHtml(siteQuery)}".</strong>`;return}const first=categoryById(matches[0].category);el.innerHTML=`<p class="search-discovery-lead">${outcome.confidence==="high"?`Looking for ${escapeHtml(first.label)}?`:"You may be looking for"}</p>`+renderDiscoveryChips(matches);el.hidden=false;statusEl.innerHTML=`<strong>No exact match for "${escapeHtml(siteQuery)}".</strong>`;await showDiscoveryProducts(matches[0],first.label)}async function showDiscoveryProducts(match,label){const listEl=document.getElementById("category-list");const el=document.getElementById("search-discovery");const res=await Api.get("searchProducts",{q:"",category:match.category,type:match.listingType||""});if(discoveryFor!==siteQuery)return;if(!res||!res.ok||!(res.products||[]).length)return;const page=(res.products||[]).slice(0,CATEGORY_PAGE_SIZE);el.insertAdjacentHTML("beforeend",`<h2 class="section-title-sm">Popular in ${escapeHtml(label)}</h2>`);listEl.innerHTML=page.map(renderCategoryTile).join("");recordProductViewsOnce(page.map(p=>p.productId))}